import networkChange from './components/subnet/networkChange'
import ipPoolList from './components/subnet/ipPoolList'

import {getDictList, getDictCmdbList} from "@/api/dict";
import {
  subnetList,
  subnetDetail,
  subnetSave,
  subnetRemove,
  getSubnetInfo,
  hasTerminal,
  initIpPool,
  syncSubnet,
  updateSubnet,
  selectSwitches,
  setCommonSubNet } from "@/api/operation/safeaccess/subnet";
import {mapGetters,mapState} from "vuex";

export default {
  components: {
    networkChange,
    ipPoolList,
  },
  data() {
    return{
      //删除时子网被占用的报错信息
      openMsg: false,
      //被占用的ip
      usedSubnetList: [],

      codeList: [{
        dictValue: '0',
        dictKey: '正常'
      }, {
        dictValue: '1',
        dictKey: '停用'
      }],
      isPublicList: [{
        dictValue: '0',
        dictKey: '否'
      }, {
        dictValue: '1',
        dictKey: '是'
      }],


      orgCodeList: [],
      swStateList: [],
      Is802List: [],
      isAccessSwitchList: [],

      searchForm: {
        current: 1,
        size: 20
      },

      dataList: [],
      selectionList: [],
      total: 0,
      tableLoading: false, //表格加载
      tableHeight: undefined,
      // 弹窗
      showForm: false,
      showType: '',
      arrtId: '',
      institutionName: '',
      showIpPoolList: false,

      deviceSourceList: [],
      deviceCategoryList: [],
      deviceTypeList: [],
      voltageLevelList: [],
    }
  },
  computed: {
    ...mapGetters(["permission"]),
    ...mapState({
      userInfo: state => state.user.userInfo
    })
  },
  mounted() {
    this.setPageContentHeight()
    this.setTableHeight()
    this.getList()


    //加载字典--工单状态

    // //加载字典--WBS元素
    this.getDictList("is3");
    //加载字典--入库仓库
    this.getDictList("swState");
    //加载字典--WBS项目
    this.getDictList("Is802");
    //加载字典--i6000同步状态
    this.getDictList("isAccessSwitch");
    //加载字典--i6000同步状态
    this.getDictList("is_to_i6000");
    // 加载字典
    this.getDictCmdbList('1102860579569664') // 设备来源
    this.getDictCmdbList('1097745625841664') // 设备分类
    this.getDictCmdbList('1097745969774592') // 设备类型
    this.getDictCmdbList('1084068218601472') // 电压等级
  },
  methods: {
    getDictCmdbList(ciId){
      //加载字典
      getDictCmdbList({ ciId: ciId }).then(res => {
        if(ciId==='1102860579569664'){ // 设备来源
          this.deviceSourceList  = res.data;
        }else if(ciId==='1097745625841664'){ // 设备分类
          this.deviceCategoryList  = res.data;
        }else if(ciId==='1097745969774592'){ // 设备类型
          this.deviceTypeList = res.data;
        }else if(ciId==='1084068218601472'){ // 电压等级
          this.voltageLevelList = res.data;
        }
      });
    },

    getDictList(code){
      //加载字典
      getDictList(code).then(res => {
        /*res.data.unshift({
          code:"",
          dictKey:'',
          dictValue:"--请选择--"})*/
        if(code==='swState'){
          this.swStateList = res.data;
        }else if(code==='Is802'){
          this.Is802List = res.data;
        }else if(code==='isAccessSwitch'){
          this.isAccessSwitchList = res.data;
        }
      });
    },
    showDictLable(code,dictList){
      //字典回显
      if(dictList!=null && code!==''){
        let items = dictList.filter(item => item.dictKey==code);
        if(items!=null && items.length>0){
          return items[0].dictValue;
        }
      }
      return code;
    },
    handleAdd(){
      this.$router.push({
        path: '/detailRoute',
        query: {
          // id: row.id,
          componentName: 'subnetInfo',
          routerTitle: '新增',
          showType: 'add'
        }
      });
    },
    handleUpdate(){
      if (this.selectionList.length !== 1) {
        this.$message({
          message: '请选择一条数据',
          type: 'warning'
        })
        return
      }

      this.$router.push({
        path: '/detailRoute',
        query: {
          arrtId: this.selectionList[0].id,
          componentName: 'subnetInfo',
          routerTitle: '修改',
          showType: 'edit'
        }
      });
    },
    handleQuery(){
      this.getList()
    },
    handleReset(){
      this.searchForm = {
        current: 1,
        size: 20
      }
      this.getList()
      this.$emit('resetClick');
    },
    handleSync(){
      if(this.selectionList.length != 1){
        return this.$message.warning('请选择一条数据！')
      }


      let params = {
          id: this.selectionList[0].id
      }
      getRadiusState(params).then(resp => {
        if(resp.data){
          this.$message({
            message:"Radius同步成功",
            type:"success"
          });
        }else{
          this.$message({
            message:"Radius同步失败",
            type:"error"
          });
        }
      })
    },

    handleCommonSubNet(){
      if (this.selectionList.length !== 1) {
        this.$message({
          message: '请选择一条数据',
          type: 'warning'
        })
        return
      }

      // let params = {
      //   id: this.selectionList[0].id,
      //   bak1: '1'
      // }
      this.$confirm('是否确认设为公共子网?', '警告', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(()=> {
        let params = JSON.parse(JSON.stringify(this.selectionList[0]))
        params.isPublic = "1"
        setCommonSubNet(params).then(response => {
          if (response.code === 200) {
            this.$message({
              message: response.msg,
              type: 'success'
            })
            this.getList()
          }
        })
      }).catch(function() {

      })
    },
    handleIpPool(){
      if (this.selectionList.length == 0) {
        this.$message({
          message: '请选择一条数据',
          type: 'warning'
        })
        return
      }
      this.arrtId = this.selectionList[0].id
      this.institutionName = this.selectionList[0].institutionName
      this.showIpPoolList = true
    },
    handleUpdateNetWork(){
      this.arrtId = this.selectionList[0].id
      this.showForm = true
    },
    handleSyncRadius(){
      if (this.selectionList.length == 0) {
        this.$message({
          message: '请选择一条数据',
          type: 'warning'
        })
        return
      }
      let params = {
        subnetId: this.selectionList[0].id
      }
      syncSubnet(params).then(resp => {
        if (resp.data) {
          this.$message({
            message: 'radius子网数据同步成功！',
            type: 'success'
          })
        } else {
          this.$message({
            message: 'radius子网数据同步失败！',
            type: 'error'
          })
        }
      })
    },
    //清理用户入网相关数据
    handleDel() {
      let _this = this
      if (_this.selectionList.length == 0) {
        _this.$message({
          message: '请选择要删除的数据',
          type: 'warning'
        })
        return
      }
      _this.$confirm('确认删除选择的子网数据吗？', '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        _this.delete()
      }).catch(() => {
        _this.$message(
          {
            type: 'warning',
            message: '已取消删除'
          }
        )
      })
    },
    delete() {
      this.usedSubnetList = []
      let ids = this.selectionList.map(el=> el.id)
      subnetRemove( this.selectionList ).then(resp => {
        let data = resp.data.list
        if (data != null && data.length > 0) {
          this.usedSubnetList = data
          this.openMsg = true
        }else {
          if (resp.code === 200) {
            this.$message({
              message: '删除成功',
              type: 'success'
            })
          }
        }
        this.getList()
      }).catch(() => {
        this.$message.error('删除子网出现异常')
      })
    },
    //关闭批量归档异常提示
    closeMsg() {
      this.usedSubnetList = []
      this.openMsg = false
    },


    showSwitcheInfo(row){
      // this.arrtId = row.id
      // this.showType = 'edit'
      // this.showForm = true
      this.$router.push({
        path: '/detailRoute',
        query: {
          arrtId: row.id,
          componentName: 'subnetInfo',
          routerTitle: '查看',
          showType: 'check'
        }
      });
    },
    selectionChange(selection) {
      //点击选择事件
      this.selectionList = selection
    },
    // 设置表格高度
    setTableHeight() {
      let bodyBox = document.getElementsByClassName('page_body')
      this.tableHeight = (bodyBox[0].offsetHeight - 240) + 'px'
    },
    getList() {
      this.tableLoading = true
      subnetList(this.searchForm).then(res => {
        this.dataList = res.data.records
        this.total = res.data.total
        this.tableLoading = false
      })
    },

  }
}
